import{_ as l,o as i,c as e,ai as r}from"./chunks/framework.Dt-5ltfC.js";const f=JSON.parse('{"title":"帮助文档（安装版）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md"}'),t={name:"guide/install.md"};function o(s,a,h,n,d,c){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="帮助文档-安装版" tabindex="-1">帮助文档（安装版） <a class="header-anchor" href="#帮助文档-安装版" aria-label="Permalink to “帮助文档（安装版）”">​</a></h1><p>本页面仅面向安装包用户，不涉及源码部署与开发环境搭建。</p><h2 id="下载与安装" tabindex="-1">下载与安装 <a class="header-anchor" href="#下载与安装" aria-label="Permalink to “下载与安装”">​</a></h2><ol><li>打开发布页下载最新安装包：<code>QQFarmCVHelper_&lt;tag&gt;_x64_setup.exe</code></li><li>运行安装包完成安装。</li><li>安装后使用桌面快捷方式启动程序（若被安全软件拦截，请手动放行）。</li><li>打开程序后点击“开始运行”。</li></ol><p>发布页：</p><ul><li><a href="https://github.com/hacker-frok/qq-farm-bot-ai/releases/latest" target="_blank" rel="noreferrer">https://github.com/hacker-frok/qq-farm-bot-ai/releases/latest</a></li></ul><h2 id="运行要求" tabindex="-1">运行要求 <a class="header-anchor" href="#运行要求" aria-label="Permalink to “运行要求”">​</a></h2><ul><li>Windows 10 / Windows 11</li></ul><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to “核心功能”">​</a></h2><ul><li>支持 QQ / 微信平台</li><li>支持隐藏小程序窗口（沉浸式运行）</li><li>一键收获 / 除草 / 除虫 / 浇水</li><li>自动买种、自动播种、自动施肥</li><li>收获后自动触发播种</li><li>好友偷取、好友帮忙、好友黑名单</li><li>每日任务 / 每日分享 / 商城福利 / QQ SVIP 领取</li><li>调度时间可自定义</li><li>好友流程冷却机制，避免无效空转</li><li>“下次再来”/“重新连接”检测与自动恢复</li><li>周期重启、休息时段暂停、每日计数持久化</li><li>模板命中区域调试预览</li><li>全局退出热键：<code>Ctrl + Shift + E</code></li><li>多开支持（多窗口、多账号）</li></ul><h2 id="建议设置-安装版用户" tabindex="-1">建议设置（安装版用户） <a class="header-anchor" href="#建议设置-安装版用户" aria-label="Permalink to “建议设置（安装版用户）”">​</a></h2><ol><li>首次运行先用默认配置，观察 10~20 分钟稳定性。</li><li>低性能设备（虚拟机/云电脑）先调大任务间隔，减少漏检弹窗。</li><li>微信平台建议先不开“隐藏小程序”，确认稳定后再尝试开启。</li><li>长时运行建议开启周期重启策略。</li></ol><h2 id="更新与升级" tabindex="-1">更新与升级 <a class="header-anchor" href="#更新与升级" aria-label="Permalink to “更新与升级”">​</a></h2><ol><li>从发布页下载最新安装包。</li><li>安装新版前关闭正在运行的程序。</li><li>安装后启动程序，检查关键开关（平台、隐藏小程序、任务间隔）是否符合预期。</li></ol><h2 id="反馈渠道" tabindex="-1">反馈渠道 <a class="header-anchor" href="#反馈渠道" aria-label="Permalink to “反馈渠道”">​</a></h2><ul><li>Telegram 群：<a href="https://t.me/qq_farm_bot_ai" target="_blank" rel="noreferrer">https://t.me/qq_farm_bot_ai</a></li><li>GitHub Issues：<a href="https://github.com/hacker-frok/qq-farm-bot-ai/issues" target="_blank" rel="noreferrer">https://github.com/hacker-frok/qq-farm-bot-ai/issues</a></li></ul>',16)])])}const m=l(t,[["render",o]]);export{f as __pageData,m as default};
